using Npgsql;
using Modules.Catalog.DTOs;
using Modules.Catalog.Entities;
using Core.Transactions;
using Shared.Primitives.Identifiers;

namespace Modules.Catalog.Repositories;

public sealed class CatalogMasterDataRepository(ITransactionCoordinator coordinator, NpgsqlDataSource dataSource)
{
    public async Task<CategoryDto> CreateCategoryAsync(TenantId tenantId, CreateCategoryRequest request, CancellationToken ct) { if (string.IsNullOrWhiteSpace(request.Name)) throw new CatalogException("catalog.category_name_required", "Category name is required."); var id = Guid.CreateVersion7(); await coordinator.ExecuteAsync(tenantId, async (context, token) => { if (request.ParentId is not null && await ScalarAsync(context, "select id from foundation_catalog.product_category where tenant_id=$1 and id=$2 and status='Active'", token, tenantId.Value, request.ParentId.Value) is null) throw new CatalogException("catalog.parent_not_found", "Parent category was not found."); await ExecuteAsync(context, "insert into foundation_catalog.product_category (tenant_id,id,name,name_normalized,parent_id,status,created_at,updated_at,version) values ($1,$2,$3,$4,$5,'Active',$6,$6,1)", token, tenantId.Value, id, request.Name.Trim(), CatalogNormalization.Search(request.Name), request.ParentId ?? (object)DBNull.Value, DateTimeOffset.UtcNow); AddEvent(context, tenantId, "CatalogCategoryCreatedV1", new { categoryId = id, request.ParentId }); return true; }, ct); return new CategoryDto(id, request.Name.Trim(), request.ParentId, CatalogStatus.Active, 1); }
    public async Task<IReadOnlyList<CategoryDto>> ListCategoriesAsync(TenantId tenantId, CancellationToken ct) { await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select id,name,parent_id,status,version from foundation_catalog.product_category where tenant_id=$1 order by name", connection); command.Parameters.AddWithValue(tenantId.Value); var result = new List<CategoryDto>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(new CategoryDto(reader.GetGuid(0), reader.GetString(1), GetGuid(reader, 2), Enum.Parse<CatalogStatus>(reader.GetString(3)), reader.GetInt64(4))); return result; }
    public async Task<BrandDto> CreateBrandAsync(TenantId tenantId, CreateBrandRequest request, CancellationToken ct) { if (string.IsNullOrWhiteSpace(request.Name)) throw new CatalogException("catalog.brand_name_required", "Brand name is required."); var id = Guid.CreateVersion7(); await coordinator.ExecuteAsync(tenantId, async (context, token) => { await ExecuteAsync(context, "insert into foundation_catalog.brand (tenant_id,id,name,name_normalized,status,created_at,updated_at,version) values ($1,$2,$3,$4,'Active',$5,$5,1)", token, tenantId.Value, id, request.Name.Trim(), CatalogNormalization.Search(request.Name), DateTimeOffset.UtcNow); AddEvent(context, tenantId, "CatalogBrandCreatedV1", new { brandId = id }); return true; }, ct); return new BrandDto(id, request.Name.Trim(), CatalogStatus.Active, 1); }
    public async Task<IReadOnlyList<BrandDto>> ListBrandsAsync(TenantId tenantId, CancellationToken ct) { await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select id,name,status,version from foundation_catalog.brand where tenant_id=$1 order by name", connection); command.Parameters.AddWithValue(tenantId.Value); var result = new List<BrandDto>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(new BrandDto(reader.GetGuid(0), reader.GetString(1), Enum.Parse<CatalogStatus>(reader.GetString(2)), reader.GetInt64(3))); return result; }
    public async Task<UomDto> CreateUomAsync(TenantId tenantId, CreateUomRequest request, CancellationToken ct) { if (string.IsNullOrWhiteSpace(request.Code) || string.IsNullOrWhiteSpace(request.NameEn)) throw new CatalogException("catalog.uom_required", "Unit code and English name are required."); var id = Guid.CreateVersion7(); await coordinator.ExecuteAsync(tenantId, async (context, token) => { await ExecuteAsync(context, "insert into foundation_catalog.uom (tenant_id,id,code,name_ar,name_en,dimension,allow_fraction,precision,status,created_at,updated_at,version) values ($1,$2,$3,$4,$5,$6,$7,$8,'Active',$9,$9,1)", token, tenantId.Value, id, CatalogNormalization.Text(request.Code), request.NameAr.Trim(), request.NameEn.Trim(), request.Dimension.ToString(), request.AllowFraction, request.Precision, DateTimeOffset.UtcNow); AddEvent(context, tenantId, "CatalogUomCreatedV1", new { uomId = id, code = CatalogNormalization.Text(request.Code), dimension = request.Dimension.ToString() }); return true; }, ct); return new UomDto(id, CatalogNormalization.Text(request.Code), request.NameAr.Trim(), request.NameEn.Trim(), request.Dimension, request.AllowFraction, request.Precision, CatalogStatus.Active); }
    public async Task<IReadOnlyList<UomDto>> ListUomsAsync(TenantId tenantId, CancellationToken ct) { await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select id,code,name_ar,name_en,dimension,allow_fraction,precision,status from foundation_catalog.uom where tenant_id=$1 and status='Active' order by code", connection); command.Parameters.AddWithValue(tenantId.Value); var result = new List<UomDto>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(new UomDto(reader.GetGuid(0), reader.GetString(1), reader.GetString(2), reader.GetString(3), Enum.Parse<UomDimension>(reader.GetString(4)), reader.GetBoolean(5), reader.GetInt16(6), Enum.Parse<CatalogStatus>(reader.GetString(7)))); return result; }
    private static async Task SetTenantAsync(NpgsqlConnection connection, TenantId tenantId, CancellationToken ct) { await using var command = new NpgsqlCommand("select set_config('app.tenant_id',$1,false)", connection); command.Parameters.AddWithValue(tenantId.Value.ToString("D")); await command.ExecuteNonQueryAsync(ct); }
    private static async Task<int> ExecuteAsync(ITransactionContext context, string sql, CancellationToken ct, params object[] values) { await using var command = new NpgsqlCommand(sql, context.Connection, context.Transaction); for (var i = 0; i < values.Length; i++) command.Parameters.AddWithValue(values[i] ?? DBNull.Value); return await command.ExecuteNonQueryAsync(ct); }
    private static async Task<Guid?> ScalarAsync(ITransactionContext context, string sql, CancellationToken ct, params object[] values) { await using var command = new NpgsqlCommand(sql, context.Connection, context.Transaction); for (var i = 0; i < values.Length; i++) command.Parameters.AddWithValue(values[i] ?? DBNull.Value); var value = await command.ExecuteScalarAsync(ct); return value is null or DBNull ? null : (Guid)value; }
    private static Guid? GetGuid(NpgsqlDataReader reader, int index) => reader.IsDBNull(index) ? null : reader.GetGuid(index);
    private static void AddEvent(ITransactionContext context, TenantId tenantId, string messageType, object payload) { var now = DateTimeOffset.UtcNow; var correlationId = Guid.CreateVersion7(); context.AddOutbox(new OutboxMessage(Guid.CreateVersion7(), messageType, System.Text.Json.JsonSerializer.Serialize(payload), tenantId, now, correlationId, correlationId, "catalog")); }
}
